The function $G_b$ and $S_b$ can be analytic continued to the whole complex plane as a meromorphic function, so that they have simple zeros at $z=Q+nb+mb^{-1}$ and simple poles at $z=-nb+-mb^{-1}$ for $n,m\in \mathbb{Z}_{\geq 0}$.

Let $\omega:=(w_1,w_2)\in \mathbb{C}^2$. The double Zeta function is defined as
\Eq{\zeta_2(s,z|\omega):=\sum_{m_1,m_2\in\mathbb{Z}_{\geq0}}(z+m_1w_1+m_2w_2)^{-s}.}

The double Gamma function is defined as
\Eq{\Gamma_2(z|\omega):=\exp\left(\frac{\partial}{\partial
s}\zeta_2(s,z|\omega)|_{s=0}\right).}

Let
\Eq{\Gamma_b(x):=\Gamma_2(x|b,b^{-1}).}

The quantum dilogarithm is defined as the function:
\Eq{S_b(x):=\frac{\Gamma_b(x)}{\Gamma_b(Q-x)},}
where $Q=b+b^{-1}$.

The main object of study is the variant given by
\Eq{\label{GS}G_b(x):=e^{\frac{\pi i}{2}x(x-Q)}S_b(x).}

 For $0\leq Re(z)\leq Q$, $G_b(z)$ can be expressed as
\Eq{\label{intform} G_b(x)=\over[\zeta_b]\exp\left(-\int_{\Omega}\frac{e^{\pi tz}}{(e^{\pi bt}-1)(e^{\pi b^{-1} t}-1)}\frac{dt}{t}\right),}
where \Eq{\zeta_b=e^{\frac{\pi i}{2}(\frac{b^2+b^{-2}}{6}+\frac{1}{2})},}
and the contour goes along $\mathbb{R}$ with a small semicircle going above the pole at $t=0$.

The integral converges absolutely for $0<Re(z)<Q$ and conditionally at the boundary.

 Self-duality:
\Eq{S_b(x)=S_{b^{-1}}(x),\;\;\;\;\;\; G_b(x)=G_{b^{-1}}(x).}

Functional equations: \Eq{\label{funceq}S_b(x+b^{\pm1})=2\sin(\pi
b^{\pm1}x)S_b(x),\;\;\;\;\;\; G_b(x+b^{\pm 1})=(1-e^{2\pi ib^{\pm 1}x})G_b(x).}

Reflection property:
\Eq{\label{reflection}S_b(x)S_b(Q-x)=1,\;\;\;\;\;\; G_b(x)G_b(Q-x)=e^{\pi
ix(x-Q)}.}

Complex conjugation: \Eq{\overline{S_b(x)}=\frac{1}{S_b(Q-\over[x])},\;\;\;\;\;\; \overline{G_b(x)}=\frac{1}{G_b(Q-\bar{x})},}

in particular 
\Eq{\left|S_b(\frac{Q}{2}+ix)\right|=\left|G_b(\frac{Q}{2}+ix)\right|=1 \mbox{ for $x\in\mathbb{R}$}.}

\label{asymp} Asymptotic properties:
\Eq{G_b(x)\sim\left\{\begin{array}{cc}\bar{\zeta_b}&Im(x)\longrightarrow+\infty,\\\zeta_b
e^{\pi ix(x-Q)}&Im(x)\longrightarrow-\infty,\end{array}\right.}
where
\Eq{\zeta_b=e^{\frac{\pi i}{4}+\frac{\pi i}{12}(b^2+b^{-2})}.}

\label{residue} Residues:
\Eq{\lim_{x\longrightarrow 0} xG_b(x)=\frac{1}{2\pi},} or more generally,
\Eq{Res\frac{1}{G_b(Q+z)}=-\frac{1}{2\pi}\prod_{k=1}^n(1-q^{2k})^{-1}\prod_{l=1}^m(1-\widetilde{q}^{2l})^{-1}}
at $z=nb+mb^{-1}, n,m\in\mathbb{Z}_{\geq0}$ and $\widetilde{q}=e^{\pi i
b^{-2}}$.

Using the functional equation \eqref{funceq}, the function can be extended to the whole complex plane using the integral formula \eqref{intform} by
\Eq{G_b(z+nQ)=G_b(x)\prod_{k=1}^n (1-e^{2\pi ib(z+(k-1)Q)}),}
\Eq{G_b(z-nQ)=G_b(x)\prod_{k=1}^n (1-e^{2\pi ib(z-kQ)})^{-1},}
where $n\in \mathbb{Z}_{\geq 0}$, $0\leq Re(z)\leq Q$.

\label{limit} The following limit holds for $b^2=ir\longrightarrow i0^+$
\Eq{\label{Glim}\lim_{r\longrightarrow 0} \frac{G_b(bz)}{\sqrt{-i}|b|  (1-q^2)^{x-1}} = \Gamma(z),}
where $\sqrt{-i}=e^{-\frac{\pi i}{4}}$ and $-\frac{\pi}{2}<\arg(1-q^2)<\frac{\pi}{2}$.

 Let $u, v$ be positive self-adjoint operators with $uv=q^2vu$, $q=e^{\pi i b^2}$. Then
\Eq{\label{qexp}g_b(u)g_b(v)=g_b(u+v),}
\Eq{\label{qpenta}g_b(v)g_b(u)=g_b(u)g_b(q^{-1} uv)g_b(v).}

 Let $s_q(w)=\prod_{n=0}^\infty (1+q^{2n+1}w)$ and define 
\Eq{\psi(p):=\frac{s_q(e^{bp})}{s_{\til[q]}(e^{p/b})},} where $\til[q]=e^{\pi ib^{-2}}$. Then $\psi(p)$ admits the integral expansion
\Eq{\psi(p):=\exp\left(\frac{1}{4}\int_\Omega \frac{e^{ip\xi/\pi}}{\sinh(b\xi)\sinh(\xi/b)}\frac{d\xi}{\xi}\right).}

 Let $a_-,a_+$ be two positive real numbers. Ruijinaars's G function is defined by
\Eq{G(a_+,a_-;z):=\exp\left(i\int_0^\infty \frac{dy}{y}\left(\frac{\sin 2yz}{2\sinh(a_+y)\sinh(a_-y)}-\frac{z}{a_+a_-y}\right)\right),}
with $|Im(z)|<(a_++a_-)/2$ and extend meromorphically to the whole complex plane.

Then \Eq{G(b,b^{-1};z)=S_b(\frac{Q}{2}-iz).}
